"""SDK boundary mock imported from pico_esp32_bridge tests."""
SDK = '\n#pragma once\n#include <stdbool.h>\n#include <stdint.h>\n#include <stddef.h>\ntypedef unsigned int uint;\ntypedef int uart_inst_t;\ntypedef int uart_parity_t;\n#define uart0 ((uart_inst_t *)1)\n#define uart1 ((uart_inst_t *)2)\n#define UART0_IRQ 20\n#define UART1_IRQ 21\n#define GPIO_FUNC_UART 2\n#define GPIO_OUT 1\n#define GPIO_IN 0\n#define UART_PARITY_NONE 0\n#define UART_PARITY_ODD 1\n#define UART_PARITY_EVEN 2\n#define CDC_LINE_CODING_STOP_BITS_2 2\n#define CDC_LINE_CODING_PARITY_ODD 1\n#define CDC_LINE_CODING_PARITY_EVEN 2\n#define TUSB_ROLE_DEVICE 1\n#define TUSB_SPEED_AUTO 0\n#define BOARD_TUD_RHPORT 0\n#define PICO_ERROR_TIMEOUT -1\ntypedef struct { uint32_t bit_rate; uint8_t stop_bits, parity, data_bits; } cdc_line_coding_t;\ntypedef struct { int role, speed; } tusb_rhport_init_t;\nstatic uint8_t incoming[32768], outgoing[32768];\nstatic uint32_t in_read, in_size, out_size, now_us, accept_limit = 128;\nstatic bool connected;\nstatic bool uart_irq_enabled;\nstatic uart_inst_t *initialized_uart;\nstatic uint32_t actual_baud, baud_changes, pin_function_mask;\nstatic uint actual_bits, actual_stops, actual_parity, installed_irq;\nstatic bool reset_requested;\nstatic uint32_t released_pins;\nstatic uint32_t gpio_outputs, gpio_high, disabled_pulls;\nstatic uint8_t host_input[4096], uart_output[4096];\nstatic uint32_t host_size, host_read, uart_out_size;\nstatic bool uart_is_readable(uart_inst_t *u) { return in_read < in_size; }\nstatic uint8_t uart_getc(uart_inst_t *u) { return incoming[in_read++]; }\nstatic uint32_t uart_set_baudrate(uart_inst_t *u, uint32_t b) {\n    if (uart_irq_enabled) __builtin_trap();\n    actual_baud = b; ++baud_changes; return b;\n}\nstatic void uart_set_format(uart_inst_t *u, uint d, uint s, uart_parity_t p) {\n    if (uart_irq_enabled) __builtin_trap();\n    actual_bits = d; actual_stops = s; actual_parity = p;\n}\nstatic void uart_init(uart_inst_t *u, uint32_t b) { initialized_uart = u; actual_baud = b; }\nstatic void uart_deinit(uart_inst_t *u) {}\nstatic void uart_set_hw_flow(uart_inst_t *u, bool a, bool b) {}\nstatic void uart_set_fifo_enabled(uart_inst_t *u, bool b) {}\nstatic void uart_set_irq_enables(uart_inst_t *u, bool a, bool b) {}\nstatic void uart_write_blocking(uart_inst_t *u, const uint8_t *b, uint32_t n) {\n    for (uint32_t i = 0; i < n; ++i) uart_output[uart_out_size++] = b[i];\n}\nstatic void irq_set_exclusive_handler(uint n, void (*h)(void)) { installed_irq = n; }\nstatic void irq_set_enabled(uint n, bool b) { uart_irq_enabled = b; }\nstatic void gpio_set_function(uint p, uint f) { pin_function_mask |= 1u << p; }\nstatic void gpio_init(uint p) { released_pins |= 1u << p; }\nstatic void gpio_disable_pulls(uint p) { disabled_pulls |= 1u << p; }\nstatic void gpio_put(uint p, bool value) {\n    if ((p == 6 || p == 7) && value) __builtin_trap();\n    if (value) gpio_high |= 1u << p; else gpio_high &= ~(1u << p);\n}\nstatic void gpio_set_dir(uint p, bool output) {\n    if (p == 2 && output && (gpio_high & (1u << p))) __builtin_trap();\n    if (output) gpio_outputs |= 1u << p; else gpio_outputs &= ~(1u << p);\n}\nstatic bool gpio_get(uint p) { return !(gpio_outputs & (1u << p)) || (gpio_high & (1u << p)); }\nstatic void reset_usb_boot(uint a, uint b) { reset_requested = true; }\nstatic void board_init(void) {}\nstatic void board_init_after_tusb(void) {}\nstatic void tusb_init(uint p, const tusb_rhport_init_t *i) {}\nstatic void tud_task(void) {}\nstatic void tight_loop_contents(void) {}\nstatic uint32_t time_us_32(void) { return now_us; }\nstatic uint64_t get_absolute_time(void) { return now_us; }\nstatic uint32_t to_ms_since_boot(uint64_t t) { return (uint32_t)(t / 1000); }\nstatic void stdio_init_all(void) {}\nstatic int stdio_usb;\nstatic void stdio_set_translate_crlf(void *driver, bool enabled) {}\nstatic int getchar_timeout_us(uint32_t timeout) { return PICO_ERROR_TIMEOUT; }\nstatic void sleep_ms(uint32_t delay) { now_us += delay * 1000; }\nstatic bool tud_cdc_connected(void) { return connected; }\nstatic uint32_t tud_cdc_available(void) { return host_size - host_read; }\nstatic uint32_t tud_cdc_read(uint8_t *b, uint32_t n) {\n    uint32_t count = 0;\n    while (count < n && host_read < host_size) b[count++] = host_input[host_read++];\n    return count;\n}\nstatic uint32_t tud_cdc_write_available(void) { return 512; }\nstatic uint32_t tud_cdc_write(const void *data, uint32_t n) {\n    const uint8_t *b = data;\n    if (n > accept_limit) n = accept_limit;\n    for (uint32_t i = 0; i < n; ++i) outgoing[out_size++] = b[i];\n    return n;\n}\nstatic void tud_cdc_write_flush(void) {}\nstatic void tud_cdc_write_clear(void) { out_size = 0; }\n'
